export async function updateProject(req: Request, actor: Actor) {
  const project = await projects.get(req.params.projectId);
  if (!project) {
    return response.notFound();
  }

  const destinationOrgId = req.body.organizationId ?? project.organizationId;
  if (!actor.organizationIds.includes(destinationOrgId)) {
    return response.forbidden();
  }

  await projects.update(project.id, {
    name: req.body.name ?? project.name,
    organizationId: destinationOrgId,
  });
  return response.noContent();
}

func FetchJSON(ctx context.Context, client *http.Client, url string, dst any) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}

	const maxBody = 1 << 20
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBody+1))
	if err != nil {
		return err
	}
	if len(body) > maxBody {
		return fmt.Errorf("response exceeds %d bytes", maxBody)
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("unexpected HTTP status %d", resp.StatusCode)
	}
	if err := json.Unmarshal(body, dst); err != nil {
		return fmt.Errorf("decode response: %w", err)
	}
	return nil
}

public final class PriceService {
  private record PriceKey(String productId, String currency, String customerTier) {}

  private final ConcurrentMap<PriceKey, Money> cache = new ConcurrentHashMap<>();
  private final PriceRepository repository;

  public PriceService(PriceRepository repository) {
    this.repository = repository;
  }

  public Money price(String productId, String currency, String customerTier) {
    PriceKey key = new PriceKey(productId, currency, customerTier);
    return cache.computeIfAbsent(
        key,
        ignored -> repository.load(productId, currency, customerTier));
  }
}

export async function applyEvent(event: AccountEvent): Promise<void> {
  await db.transaction(async (tx) => {
    const claimed = await tx.query(
      `INSERT INTO processed_events (event_id)
       VALUES ($1)
       ON CONFLICT (event_id) DO NOTHING
       RETURNING event_id`,
      [event.id],
    );

    if (claimed.rowCount === 0) {
      return;
    }

    await applyAccountChange(tx, event);
  });
}

func Reserve(ctx context.Context, db *sql.DB, sku string, qty int) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	var available int
	if err := tx.QueryRowContext(ctx,
		"SELECT available FROM inventory WHERE sku = $1", sku,
	).Scan(&available); err != nil {
		return err
	}
	if available < qty {
		return ErrInsufficientStock
	}
	if _, err := tx.ExecContext(ctx,
		"UPDATE inventory SET available = available - $1 WHERE sku = $2", qty, sku,
	); err != nil {
		return err
	}
	return tx.Commit()
}

def valid_signature?(body, provided, secret)
  return false unless provided.is_a?(String)
  return false unless provided.match?(/\A[0-9a-fA-F]{64}\z/)

  expected = OpenSSL::HMAC.hexdigest("SHA256", secret, body)
  ActiveSupport::SecurityUtils.secure_compare(expected, provided.downcase)
end

from urllib.parse import urlparse

import requests

ALLOWED_HOSTS = {"artifacts.example.com", "mirror.example.com"}

def fetch_manifest(url: str) -> dict:
    parsed = urlparse(url)
    if parsed.scheme != "https" or parsed.hostname not in ALLOWED_HOSTS:
        raise ValueError("manifest URL is not allowed")

    response = requests.get(url, timeout=2, allow_redirects=False)
    if response.is_redirect or response.is_permanent_redirect:
        raise ValueError("manifest redirect is not allowed")
    response.raise_for_status()
    return response.json()

public final class RefreshCoordinator {
  private final Map<String, CompletableFuture<Void>> active = new HashMap<>();
  private final Executor executor;
  private final Loader loader;

  public CompletableFuture<Void> refresh(String key) {
    synchronized (active) {
      CompletableFuture<Void> existing = active.get(key);
      if (existing != null) {
        return existing;
      }

      CompletableFuture<Void> created = new CompletableFuture<>();
      active.put(key, created);
      try {
        executor.execute(() -> {
          try {
            loader.refresh(key);
            created.complete(null);
          } catch (Throwable failure) {
            created.completeExceptionally(failure);
            return;
          }
          synchronized (active) {
            active.remove(key);
          }
        });
      } catch (RuntimeException submissionFailure) {
        active.remove(key);
        created.completeExceptionally(submissionFailure);
      }
      return created;
    }
  }
}

export async function capturePayment(gateway, paymentId, amount) {
  const idempotencyKey = crypto.randomUUID();
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      return await gateway.capture({
        paymentId,
        amount,
        idempotencyKey,
      });
    } catch (error) {
      if (!isTimeout(error)) {
        throw error;
      }
      lastError = error;
    }
  }
  throw lastError;
}
